:root{--marble:url("/uploads/home-bg-texture.jpg")}

:root{
--navy:#0A1A33;--navy2:#0E2A4F;--navy3:#133A6B;
--blue:#0090D8;--blue2:#38B6EF;--blue-soft:#E8F5FD;
--red:#E63312;--red2:#B81F05;
--steel:#C8D4DE;--ink:#15222F;--mut:#5A6E82;--line:#E2E9F1;--bg:#F4F8FC;
--gut:20px;--rad:16px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:Outfit,system-ui,Arial,sans-serif;color:var(--ink);background:#fff;line-height:1.65;font-size:16.5px;-webkit-font-smoothing:antialiased}
svg{width:18px;height:18px;flex-shrink:0}
img{max-width:100%;display:block;height:auto}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4,h5{font-family:'Barlow Semi Condensed',Outfit,sans-serif;line-height:1.08;color:var(--navy);font-weight:700;letter-spacing:-.01em}
h1{font-size:clamp(2.3rem,5.2vw,4.1rem);font-weight:800;text-transform:uppercase}
h2{font-size:clamp(1.9rem,3.8vw,3rem);font-weight:800;text-transform:uppercase}
h3{font-size:clamp(1.25rem,1.9vw,1.6rem);font-weight:700}
h4{font-size:1.12rem}
p{overflow-wrap:anywhere}
.wrap{max-width:1240px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:84px;padding-bottom:84px}
.sec.alt{background:var(--bg)}
.sec.dark{background:linear-gradient(145deg,var(--navy) 0%,#07162B 60%,var(--navy2) 100%);color:#D7E6F3}
.sec.dark h2,.sec.dark h3,.sec.dark h4{color:#fff}
.center{text-align:center}
.lead{font-size:1.1rem;color:var(--mut)}
.sec.dark .lead{color:#AFC6DC}
.eyebrow{display:inline-flex;align-items:center;gap:.55rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:.95rem;letter-spacing:.18em;text-transform:uppercase;color:var(--blue);margin-bottom:.55rem}
.eyebrow::before{content:"";width:26px;height:3px;border-radius:2px;background:var(--red)}
.sec.dark .eyebrow{color:var(--blue2)}
.shead{max-width:46rem}
.shead.center{margin-left:auto;margin-right:auto}
.skip{position:absolute;left:-999px}
.skip:focus{left:12px;top:12px;z-index:999;background:#fff;color:var(--navy);padding:10px 16px;border-radius:8px}
a:focus-visible,button:focus-visible,label:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--blue2);outline-offset:2px}

/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:1.05rem;letter-spacing:.04em;text-transform:uppercase;border:0;border-radius:6px;padding:.85rem 1.5rem;cursor:pointer;transition:background .18s,transform .18s,box-shadow .18s;white-space:nowrap;line-height:1.2}
