.socials svg{width:18px;height:18px}
.fbar{border-top:1px solid rgba(255,255,255,.12);margin-top:44px;padding-top:22px;display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;font-size:.86rem;align-items:center}
.built{display:inline-flex;align-items:center;gap:.5rem;color:#8EA9C2}
.built b{color:var(--blue2)}
