/* quote drawer */
.qopen{cursor:pointer}
.qscrim{position:fixed;inset:0;background:rgba(6,16,30,.6);opacity:0;visibility:hidden;transition:.3s;z-index:980;cursor:pointer}
.qdrawer{position:fixed;top:0;right:0;height:100%;width:min(440px,94vw);background:#fff;z-index:990;clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .36s cubic-bezier(.4,0,.2,1);box-shadow:-14px 0 50px rgba(6,16,30,.3);overflow-y:auto;display:flex;flex-direction:column}
#qtog:checked~.qscrim{opacity:1;visibility:visible}
#qtog:checked~.qdrawer{clip-path:inset(0 0 0 0);pointer-events:auto}
.qhead{position:relative;background:linear-gradient(150deg,var(--navy) 0%,#0B2140 60%,var(--navy2) 100%);color:#fff;padding:26px 26px 22px;overflow:hidden}
.qart{position:absolute;right:-6px;top:-10px;width:168px;height:190px;opacity:.95;pointer-events:none}
.qhead .eyebrow{color:var(--blue2);position:relative;z-index:2}
.qhead h3{color:#fff;font-size:1.5rem;position:relative;z-index:2;max-width:15rem}
.qhead p{color:#A9C1D7;font-size:.9rem;margin-top:.45rem;position:relative;z-index:2;max-width:17rem}
.qclose{position:absolute;top:14px;right:16px;width:34px;height:34px;border-radius:9px;background:rgba(255,255,255,.14);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:5}
.qclose:hover{background:var(--red)}
.qclose svg{width:16px;height:16px}
.qbody{padding:22px 26px 30px;background:var(--navy);color:#D7E6F3;flex:1}
.qbody .fnote{margin-top:1rem}
.qtabs{display:flex;gap:0;background:var(--navy2);border-bottom:1px solid rgba(255,255,255,.1)}
.qtabs a{flex:1;text-align:center;padding:13px 10px;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#A9C1D7;font-size:.98rem;display:flex;align-items:center;justify-content:center;gap:.4rem}
.qtabs a:hover{background:var(--red);color:#fff}
.qtabs svg{width:15px;height:15px}

/* sticky mobile bar */
.mbar{display:none}

/* back to top */
.totop{position:fixed;right:18px;bottom:78px;width:46px;height:46px;border-radius:12px;background:var(--navy);color:#fff;display:flex;align-items:center;justify-content:center;z-index:700;box-shadow:0 12px 26px rgba(10,26,51,.3)}
.totop:hover{background:var(--red)}
.totop svg{width:20px;height:20px}

/* reveal */
.rv{animation:rvIn .8s both}
.rv2{animation-delay:.12s}
.rv3{animation-delay:.24s}
.rv4{animation-delay:.36s}
@keyframes rvIn{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}.band .track,.rail span{animation:none}}

/* responsive */
@media(max-width:1180px){
 .g4{grid-template-columns:repeat(3,minmax(0,1fr))}
