 .nav>ul>li>a::after,.nav>ul>li>.drop-lbl::after{display:none}
 .submenu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;border-radius:0;min-width:0;padding:0;max-height:0;overflow:hidden;transition:max-height .3s;background:var(--bg)}
 .dtog:checked~.submenu{max-height:760px;padding:.4rem 0 .7rem}
