 .nav .navclose{display:flex;position:absolute;top:18px;right:20px;width:40px;height:40px;border-radius:10px;background:var(--navy);color:#fff;align-items:center;justify-content:center;cursor:pointer}
 .nav .navclose svg{width:16px;height:16px}
 .hero .wrap{grid-template-columns:1fr;gap:40px}
