 footer.site .cols{grid-template-columns:repeat(2,minmax(0,1fr))}
 .rail{display:none}
 .mbar{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:800;background:#fff;border-top:1px solid var(--line);box-shadow:0 -4px 20px rgba(10,26,51,.12)}
 .mbar>*{flex:1;display:flex;align-items:center;justify-content:center;gap:.45rem;padding:14px 8px;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--navy);cursor:pointer;font-size:1rem}
