/* ============ v2: reference-matched header, hero, why-choose, about ============ */

/* --- hazard rails that run behind header + hero --- */
.bandbg{position:relative;background:linear-gradient(135deg,#F2F8FD 0%,#FFFFFF 42%,#EAF4FC 100%)}
.bandbg::before,.bandbg::after{content:"";position:absolute;top:0;bottom:0;height:auto;transform:none;width:46px;z-index:1;background:repeating-linear-gradient(45deg,#0A1A33 0 11px,#FFFFFF 11px 22px);opacity:.92}
.bandbg::before{left:0}.bandbg::after{right:0}
.railbg{display:none}
.railtxt{position:absolute;top:0;bottom:0;width:46px;z-index:2;display:flex;align-items:center;justify-content:center;overflow:hidden;pointer-events:none}
.railtxt.l{left:46px}.railtxt.r{right:46px;display:none}
.railtxt span{writing-mode:vertical-rl;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;letter-spacing:.14em;text-transform:none;font-size:1.05rem;color:var(--navy);white-space:nowrap;display:flex;align-items:center;gap:1.6rem;animation:railRoll 30s linear infinite}
.railtxt.r span{animation-direction:reverse}
.railtxt span i{width:10px;height:10px;border-radius:50%;background:var(--red);display:block;flex:none}
@keyframes railRoll{from{transform:translateY(-22%)}to{transform:translateY(22%)}}
.bandbg>.wrap{position:relative;z-index:3}
header.site.bandbg::before,header.site.bandbg::after{opacity:.55}

/* --- util pill (credit cards) --- */
.util{background:transparent;padding-top:16px}
.util .wrap{display:block;min-height:0}
.util-pill{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:nowrap;
 background:linear-gradient(100deg,#0A1A33 0%,#10305A 55%,#0A1A33 100%);border-radius:999px;
 padding:.62rem 1.5rem;box-shadow:0 10px 30px rgba(10,26,51,.2);position:relative;overflow:hidden}
.util-pill::after{content:"";position:absolute;top:0;left:-40%;width:28%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.16),transparent);transform:skewX(-20deg);animation:pillShine 6s ease-in-out infinite}
@keyframes pillShine{0%{left:-40%}55%{left:130%}100%{left:130%}}
.pay{display:flex;align-items:center;gap:.7rem;white-space:nowrap;color:#fff;font-size:.92rem;font-weight:600;position:relative;z-index:2}
.pay b{color:var(--blue2);font-family:'Barlow Semi Condensed',sans-serif;font-size:1.05rem;letter-spacing:.02em}
.cards{display:flex;gap:.35rem;align-items:center}
.cards span{display:inline-flex;align-items:center;justify-content:center;width:40px;height:26px;border-radius:5px;background:#fff;font-family:'Barlow Semi Condensed',sans-serif;font-weight:800;font-size:.72rem;letter-spacing:.02em;color:var(--navy);box-shadow:0 2px 8px rgba(0,0,0,.25)}
.cards span.v{color:#1A3A8F}.cards span.m{color:#C8321E}.cards span.a{color:#0E7FC0}.cards span.p{color:#0A7A4A}
.util-r{display:flex;align-items:center;gap:1.3rem;flex-wrap:nowrap;position:relative;z-index:2;white-space:nowrap}
.util-r a,.util-r span{display:inline-flex;align-items:center;gap:.42rem;color:#C6DCEF;font-size:.9rem;font-weight:600}
.util-r a{color:#fff}
.util-r a:hover{color:var(--blue2)}
.util-r svg{width:15px;height:15px;color:var(--blue2)}

/* --- header v2 --- */
header.site{position:sticky;top:0;z-index:900;background:rgba(255,255,255,.92);backdrop-filter:blur(8px);border-bottom:1px solid rgba(10,26,51,.08);box-shadow:0 2px 24px rgba(10,26,51,.06)}
.hdr-in{min-height:94px;gap:1.2rem}
.brand{flex-direction:row;align-items:center;gap:.7rem}
.brand img{width:92px}
.brand .btxt{display:block}
.brand .btxt b{display:block;font-family:'Barlow Semi Condensed',sans-serif;font-weight:800;font-size:1.42rem;color:var(--navy);line-height:1;letter-spacing:.01em;text-transform:uppercase}
.brand .btxt small{display:block;font-size:.72rem;color:var(--mut);letter-spacing:.17em;text-transform:uppercase;font-weight:600;margin-top:.22rem}
header.site .wrap,.util .wrap,.hero>.wrap{max-width:1400px}
.nav{margin-left:auto;margin-right:auto}
.nav>ul{gap:1.1rem}
.nav a,.drop-lbl{white-space:nowrap;font-size:1.04rem}
.hcall{display:flex}
.hcall a.num{font-family:'Barlow Semi Condensed',sans-serif;font-size:1.3rem;color:var(--navy);line-height:1.05;font-weight:800;display:block}
.hcall a.num:hover{color:var(--red)}
.hcall .ic{background:var(--red);color:#fff;transition:transform .3s}
.hcall:hover .ic{transform:rotate(-12deg) scale(1.06)}

/* --- animated buttons --- */
.btn{position:relative;overflow:hidden;isolation:isolate}
.btn::before{content:"";position:absolute;top:0;left:-140%;width:55%;height:100%;z-index:-1;background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent);transform:skewX(-22deg);transition:left .65s cubic-bezier(.4,0,.2,1)}
.btn:hover::before{left:150%}
.btn svg{transition:transform .28s}
.btn:hover svg{transform:translateX(4px)}
.btn-red{animation:redPulse 3s ease-in-out infinite}
.btn-red:hover{animation:none}
@keyframes redPulse{0%,100%{box-shadow:0 8px 20px rgba(230,51,18,.28)}50%{box-shadow:0 8px 20px rgba(230,51,18,.28),0 0 0 10px rgba(230,51,18,.08)}}
.btn-pill{border-radius:999px;padding-right:.5rem;gap:1rem}
.btn-pill .cir{width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,.2);display:inline-flex;align-items:center;justify-content:center;flex:none;transition:transform .3s,background .3s}
.btn-pill:hover .cir{background:#fff;transform:rotate(45deg)}
.btn-pill:hover .cir svg{transform:none}
.btn-red.btn-pill:hover .cir{color:var(--red)}
.btn-navy.btn-pill:hover .cir{color:var(--navy)}
@media (prefers-reduced-motion:reduce){.btn-red{animation:none}.util-pill::after{animation:none}}

/* --- hero v2 (boxed slider card) --- */
.hero{overflow:visible;padding:30px 0 60px}
.hero .wrap{display:block;padding-top:0;padding-bottom:0;position:relative;z-index:3}
.hbox{position:relative;border-radius:26px;overflow:hidden;box-shadow:0 30px 70px rgba(10,26,51,.26);background:var(--navy)}
.hsr{position:absolute;opacity:0;width:0;height:0;pointer-events:none}
.hslides{position:relative}
.hslide{display:none;position:relative;min-height:540px}
.hs1:checked~.hslides .hslide:nth-child(1),
.hs2:checked~.hslides .hslide:nth-child(2),
.hs3:checked~.hslides .hslide:nth-child(3){display:block;animation:hsIn .7s both}
@keyframes hsIn{from{opacity:0}to{opacity:1}}
.hslide>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.hslide::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,20,38,.42) 0%,rgba(8,20,38,.66) 42%,rgba(8,20,38,.9) 100%)}
.hsin{position:relative;z-index:3;display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:40px;align-items:center;padding:64px 58px 86px}
.hstext{grid-column:2}
.hero h1{color:#fff;margin:.5rem 0 0}
.hero h1 em{font-style:normal;color:var(--blue2);display:block}
.hero .sub{font-size:1.14rem;color:#C6DCEF;margin:1.05rem 0 1.5rem;max-width:34rem}
.hero .eyebrow{color:var(--blue2)}
.hero .eyebrow::before{background:var(--red)}
.hchips{display:flex;flex-wrap:wrap;gap:.5rem;margin-bottom:1.5rem}
.hchips span{display:inline-flex;align-items:center;gap:.4rem;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);padding:.42rem .9rem;border-radius:999px;font-size:.86rem;font-weight:600;color:#fff}
.hchips svg{width:14px;height:14px;color:var(--blue2)}
.hcta{display:flex;gap:.8rem;flex-wrap:wrap;align-items:center}
.hnav{position:absolute;right:46px;bottom:34px;z-index:5;display:flex;align-items:center;gap:1rem}
.hnav .cnt{font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;color:#fff;letter-spacing:.14em;font-size:1.02rem}
.hnav .cnt b{color:var(--blue2)}
.harrow{width:44px;height:44px;border-radius:50%;border:1.6px solid rgba(255,255,255,.4);display:flex;align-items:center;justify-content:center;color:#fff;cursor:pointer;transition:.25s}
.harrow:hover{background:var(--red);border-color:var(--red)}
.harrow svg{width:17px;height:17px}
.harrow.p svg{transform:scaleX(-1)}
.hbadge2{position:absolute;left:46px;bottom:34px;z-index:5;display:flex;align-items:center;gap:.85rem;background:rgba(255,255,255,.95);border-radius:14px;padding:12px 18px;box-shadow:0 16px 36px rgba(0,0,0,.28)}
.hbadge2 .n{font-family:'Barlow Semi Condensed',sans-serif;font-weight:800;font-size:2rem;color:var(--red);line-height:1}
.hbadge2 b{display:block;font-family:'Barlow Semi Condensed',sans-serif;font-size:1.02rem;color:var(--navy);line-height:1.15}
.hbadge2 small{display:block;font-size:.76rem;color:var(--mut)}

/* --- why choose us v2 (circles) --- */
.wcs{background:linear-gradient(180deg,#EAF4FC 0%,#F4FAFE 56%,#FFFFFF 56%,#FFFFFF 100%)}
.wcard{text-align:center}
.wimg{position:relative;width:min(100%,290px);margin:0 auto 2.5rem}
.wimg img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:50%;box-shadow:0 22px 48px rgba(10,26,51,.18)}
.wimg .wico{position:absolute;left:50%;bottom:-30px;transform:translateX(-50%);width:68px;height:68px;border-radius:50%;background:var(--red);color:#fff;display:flex;align-items:center;justify-content:center;box-shadow:0 12px 26px rgba(230,51,18,.4);border:5px solid #fff;transition:transform .3s}
.wimg .wico svg{width:28px;height:28px}
.wcard:hover .wimg .wico{transform:translateX(-50%) rotate(-10deg) scale(1.06)}
.wcard h3{font-size:1.45rem;margin-bottom:.4rem}
.wcard p{color:var(--mut);max-width:22rem;margin:0 auto}
.wcard .more{display:inline-flex;align-items:center;gap:.4rem;margin-top:.9rem;color:var(--blue);font-weight:700;font-family:'Barlow Semi Condensed',sans-serif;text-transform:uppercase;letter-spacing:.06em}
.wcard .more svg{width:14px;height:14px;transition:transform .25s}
.wcard .more:hover svg{transform:translateX(4px)}

/* --- about v2 --- */
.about2{position:relative;padding:92px 0;background:#fff}
.about2::before{content:"";position:absolute;right:0;top:0;bottom:0;width:74%;background:linear-gradient(135deg,#F2F8FD,#EAF4FC);border-radius:34px 0 0 34px}
.ab-grid{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:48px;align-items:center}
.ab-media{position:relative}
.ab-media img{width:100%;aspect-ratio:4/3.1;object-fit:cover;border-radius:6px;box-shadow:0 28px 60px rgba(10,26,51,.22)}
.ab-media::before{content:"";position:absolute;left:-11px;top:18px;bottom:18px;width:11px;background:var(--red);border-radius:5px 0 0 5px}
.ab-row{display:grid;grid-template-columns:minmax(0,.86fr) minmax(0,1.14fr);gap:30px;align-items:center;margin:1.6rem 0}
.ab-inset{position:relative;border-radius:10px;overflow:hidden;box-shadow:0 18px 40px rgba(10,26,51,.2)}
.ab-inset img{width:100%;aspect-ratio:16/10;object-fit:cover}
.ab-inset .abtag{position:absolute;left:0;right:0;bottom:0;background:linear-gradient(180deg,transparent,rgba(10,26,51,.92));color:#fff;padding:26px 14px 12px;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:.98rem;text-align:center;letter-spacing:.03em}
.ticks2{list-style:none}
.ticks2 li{display:flex;align-items:center;gap:.7rem;padding:.62rem 0;border-bottom:1.5px solid rgba(10,26,51,.1);font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:1.18rem;color:var(--navy)}
.ticks2 li:last-child{border-bottom:0}
.ticks2 li svg{width:21px;height:21px;color:#fff;background:var(--red);border-radius:50%;padding:4px;flex:none}
.ab-bot{display:flex;align-items:center;gap:1.5rem;flex-wrap:wrap;margin-top:.6rem}
.ab-or{color:var(--mut);font-weight:600}

/* --- side quote tab (slide out) --- */
.stab{position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:860;display:flex;align-items:stretch}
.stab-card{width:0;opacity:0;overflow:hidden;transition:width .4s cubic-bezier(.4,0,.2,1),opacity .3s;background:#0A1A33;border-radius:16px 0 0 16px;box-shadow:-14px 0 44px rgba(6,16,30,.32);display:flex;flex-direction:column;justify-content:center;gap:1.1rem;padding:0}
.stab:hover .stab-card,.stab:focus-within .stab-card{width:238px;opacity:1;padding:26px 22px}
.stab-card .si{display:flex;flex-direction:column;align-items:center;text-align:center;gap:.5rem;color:#C6DCEF;font-size:.8rem;font-weight:600;line-height:1.35;white-space:normal;width:194px}
.stab-card .si b{color:#fff;font-family:'Barlow Semi Condensed',sans-serif;font-size:1.02rem;letter-spacing:.04em;text-transform:uppercase}
