/* --- why choose us sits on the same marble, fading to white --- */
.wcs{background:transparent;position:relative}
.wcs>.wrap{z-index:2}
body{position:relative}

/* --- side quote tab: lower right --- */
.stab{top:auto;bottom:26px;transform:none;align-items:flex-end}
.stab-panel{min-height:324px;width:70px}
.stab-lbl{font-size:1.34rem}
.stab-art2{width:118px;height:128px;top:-84px}
.stab-card{align-self:flex-end}
.totop{right:auto;left:18px;bottom:24px}
@media(max-width:1060px){.totop{left:14px;bottom:70px}}


@media(max-width:1200px){.hbox{min-height:0}.hsin{padding:54px 36px}}
@media(max-width:620px){.hero{padding:14px 0 36px}.hsin{padding:38px 20px 44px}.hbox{border-radius:20px}}

/* ============ v6 ============ */

/* --- rails: full height of the marble band, 50% larger --- */
.rail2{position:absolute;top:0;bottom:auto;height:calc(100% - var(--split,372px));width:224px;z-index:1;pointer-events:none;overflow:hidden}
.rail2.l{left:0}.rail2.r{right:0}
.rail2 .stripe{position:absolute;top:0;bottom:0;width:93px;background:repeating-linear-gradient(45deg,#0A1A33 0 21px,#FFFFFF 21px 42px);background-size:auto 119px;animation:stripeDown 3.4s linear infinite}
.rail2.l .stripe{left:0}
.rail2.r .stripe{right:0;animation-name:stripeUp}
.rail2 .rtx{position:absolute;top:0;bottom:0;width:104px;display:flex;align-items:center;justify-content:center;overflow:hidden}
.rail2.l .rtx{left:103px}
.rail2.r .rtx{right:103px}
.rail2 .rtx span{writing-mode:vertical-rl;font-family:Outfit,sans-serif;font-weight:800;font-size:3rem;letter-spacing:-.02em;color:var(--navy);white-space:nowrap;display:flex;align-items:center;gap:3.4rem;animation:railUpDn 30s linear infinite}
.rail2.r .rtx span{animation-name:railDnUp}
.rail2 .rtx span i{width:26px;height:26px;border-radius:50%;background:var(--red);display:block;flex:none}
@keyframes stripeDown{from{background-position:0 0}to{background-position:0 119px}}
@keyframes stripeUp{from{background-position:0 0}to{background-position:0 -119px}}
@media(max-width:1919px){.rail2{display:none}}
@media (prefers-reduced-motion:reduce){.rail2 .stripe,.rail2 .rtx span{animation:none}}

/* --- breathing room above the logo --- */
.hdr-in{min-height:112px;padding-top:14px}
.util{padding-top:20px}

/* --- horizontal quote bar, lower right --- */
.stab{position:fixed;right:22px;bottom:22px;top:auto;left:auto;transform:none;z-index:860;display:flex;align-items:stretch;border-radius:14px;overflow:hidden;box-shadow:0 18px 44px rgba(6,16,30,.3)}
.stab-card{display:flex;flex-direction:row;align-items:center;gap:0;width:0;opacity:0;padding:0;background:#16202c;border-radius:0;box-shadow:none;overflow:hidden;transition:width .42s cubic-bezier(.4,0,.2,1),opacity .3s,padding .42s;position:relative;align-self:stretch}
.stab-card::before{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.14) 1.3px,transparent 1.4px);background-size:9px 9px;opacity:.9}
.stab:hover .stab-card,.stab:focus-within .stab-card{width:716px;padding:0 6px 0 14px}
.stab-card .si{position:relative;z-index:2;display:flex;flex-direction:row;align-items:center;text-align:left;gap:.7rem;color:#AFC6DC;font-size:.76rem;font-weight:500;line-height:1.35;white-space:normal;width:216px;flex:none;padding:0 .8rem}
.stab-card .si .tx{display:block;min-width:0}
.stab-card .si b{display:block;color:#fff;font-family:Outfit,sans-serif;font-weight:800;font-size:.9rem;letter-spacing:.01em;text-transform:uppercase;margin-bottom:.12rem}
.stab-card .si .ic{width:40px;height:40px;border-radius:50%;background:rgba(230,51,18,.2);color:var(--red);display:flex;align-items:center;justify-content:center;flex:none}
.stab-card .si .ic svg{width:20px;height:20px}
.stab-card hr{border:0;border-left:1px dashed rgba(255,255,255,.2);border-top:0;width:0;height:52px;align-self:center;margin:0;flex:none;position:relative;z-index:2}
.stab-panel{position:relative;width:auto;min-height:0;display:flex;flex-direction:row;align-items:center;gap:1rem;background:linear-gradient(180deg,var(--red),var(--red2));border-radius:0;box-shadow:none;cursor:pointer;padding:18px 24px 18px 26px;overflow:hidden}
.stab-panel::before{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.16) 1.3px,transparent 1.4px);background-size:9px 9px;opacity:.55}
.stab-panel::after{content:"";position:absolute;top:0;left:-45%;width:34%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.26),transparent);transform:skewX(-20deg);animation:tabShine2 5s ease-in-out infinite}
@keyframes tabShine2{0%{left:-45%}58%{left:140%}100%{left:140%}}
.stab-lbl{position:relative;z-index:2;writing-mode:horizontal-tb;transform:none;font-family:Outfit,sans-serif;font-weight:800;font-size:1.22rem;letter-spacing:.03em;text-transform:uppercase;color:#fff;white-space:nowrap;margin:0;padding:0;text-shadow:none}
.stab-lbl em{font-style:normal;color:#0A1A33}
.stab-go{position:relative;z-index:2;width:auto;background:transparent;padding:0;border-radius:0;clip-path:none;display:flex;align-items:center}
.stab-go span{width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;color:#fff;transition:transform .3s,background .3s}
.stab-go span svg{width:18px;height:18px}
.stab:hover .stab-go span{background:#fff;color:var(--red);transform:translateX(4px)}
.stab-art2,.stab-drip,.stab-head{display:none!important}
.totop{left:22px;bottom:22px;right:auto}
@media(max-width:1180px){.stab{display:none}.totop{left:14px;bottom:70px}}
@media (prefers-reduced-motion:reduce){.stab-panel::after{animation:none}}



/* --- tablet and small-desktop corrections --- */
@media(max-width:1200px){
 .hbox{display:block;min-height:0}
