/* --- footer accreditation strip --- */
.facc{margin-top:40px;padding-top:30px;border-top:1px solid rgba(255,255,255,.12);text-align:center}
.facc-h{display:block;font-family:Outfit,sans-serif;font-weight:800;font-size:.86rem;letter-spacing:.18em;text-transform:uppercase;color:#7F9AB4;margin-bottom:1.3rem;text-align:center}
.facc-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;max-width:860px;margin:0 auto;justify-items:center;align-items:center}
.facc-row img{width:100%;height:auto;border-radius:9px;background:#fff;padding:9px 12px;filter:saturate(.9);transition:transform .25s,box-shadow .25s}
.facc-row img:hover{transform:translateY(-3px);box-shadow:0 14px 28px rgba(0,0,0,.3)}
@media(max-width:760px){.facc-row{grid-template-columns:repeat(2,minmax(0,1fr));max-width:100%}}

/* --- premium horizontal quote bar --- */
.stab{right:24px;bottom:24px;border-radius:18px;box-shadow:0 22px 54px rgba(6,16,30,.38),0 0 0 1px rgba(255,255,255,.06)}
.stab-card{background:linear-gradient(135deg,#101C2C 0%,#16263A 52%,#101C2C 100%)}
.stab-card .si{transform:translateY(10px);opacity:0;transition:transform .5s cubic-bezier(.2,.8,.2,1),opacity .4s}
.stab:hover .stab-card .si,.stab:focus-within .stab-card .si{transform:none;opacity:1}
.stab:hover .stab-card .si:nth-of-type(1){transition-delay:.10s}
.stab:hover .stab-card .si:nth-of-type(2){transition-delay:.17s}
.stab:hover .stab-card .si:nth-of-type(3){transition-delay:.24s}
.stab-card .si .ic{background:linear-gradient(140deg,rgba(230,51,18,.38),rgba(230,51,18,.14));box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}
.stab-card hr{opacity:0;transition:opacity .4s .22s}
.stab:hover .stab-card hr{opacity:1}
.stab-panel{background:linear-gradient(135deg,#F2491F 0%,#E63312 46%,#B81F05 100%);padding:20px 34px 20px 32px;gap:1.2rem}
.stab-panel::before{background-image:radial-gradient(rgba(255,255,255,.2) 1.3px,transparent 1.4px);background-size:10px 10px;opacity:.5}
.stab-lbl{font-size:1.26rem;letter-spacing:.035em}
.stab-lbl em{color:#0A1A33;position:relative}
.stab-lbl em::after{content:"";position:absolute;left:0;right:0;bottom:-3px;height:2px;background:rgba(10,26,51,.55);transform:scaleX(0);transform-origin:left;transition:transform .4s cubic-bezier(.2,.8,.2,1)}
.stab:hover .stab-lbl em::after{transform:scaleX(1)}
.stab-go span{background:rgba(255,255,255,.22);box-shadow:inset 0 0 0 1px rgba(255,255,255,.3)}
.stab-go span::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:1.5px solid rgba(255,255,255,.5);opacity:0;animation:goPing 2.6s ease-out infinite}
.stab-go span{position:relative}
@keyframes goPing{0%{transform:scale(.84);opacity:.7}70%{transform:scale(1.14);opacity:0}100%{opacity:0}}
.stab-pulse{position:absolute;left:0;right:0;bottom:0;height:3px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.85),transparent);transform:translateX(-100%);animation:barSweep 3.4s ease-in-out infinite;z-index:3;pointer-events:none}
@keyframes barSweep{0%{transform:translateX(-100%)}55%{transform:translateX(100%)}100%{transform:translateX(100%)}}
@media (prefers-reduced-motion:reduce){.stab-go span::after,.stab-pulse{animation:none;opacity:0}}
@media(min-width:1181px){.fbar{padding-bottom:0}footer.site{padding-bottom:116px}}

/* --- hero box matches the header width --- */
.hero>.wrap{max-width:1400px}
.hsin{padding:76px 76px 104px}
@media(max-width:1400px){.hsin{padding:68px 56px 92px}}
@media(max-width:1200px){.hsin{padding:52px 40px 22px}
 .hero .hbadge2{margin:0 40px 14px;max-width:calc(100% - 80px)}
 .hero .hrate{margin:0 40px 34px;max-width:calc(100% - 80px)}}
@media(max-width:860px){.hsin{padding:46px 30px 20px}
 .hero .hbadge2{margin:0 30px 12px;max-width:calc(100% - 60px)}
 .hero .hrate{margin:0 30px 28px;max-width:calc(100% - 60px)}}
@media(max-width:620px){.hsin{padding:38px 22px 18px}
 .hero .hbadge2{margin:0 22px 12px;max-width:calc(100% - 44px)}
 .hero .hrate{margin:0 22px 24px;max-width:calc(100% - 44px)}}

/* --- keep the hero headline to exactly two lines from tablet up --- */
@media(min-width:1201px){
 .hstext{container-type:inline-size}
 .hero h1{font-size:clamp(2rem,7.8cqw,4.15rem)}
 .hero h1 em{white-space:nowrap}
}
