.stab-card .si{display:flex;flex-direction:column;align-items:center;text-align:center;gap:.5rem;color:#C6DCEF;font-size:.8rem;font-weight:600;line-height:1.35;white-space:normal;width:194px}
.stab-card .si b{color:#fff;font-family:'Barlow Semi Condensed',sans-serif;font-size:1.02rem;letter-spacing:.04em;text-transform:uppercase}
.stab-card .si .ic{width:42px;height:42px;border-radius:50%;background:rgba(230,51,18,.16);color:var(--red);display:flex;align-items:center;justify-content:center}
.stab-card .si .ic svg{width:20px;height:20px}
.stab-card hr{border:0;border-top:1px dashed rgba(255,255,255,.18);width:100%}
.stab-btn{position:relative;width:62px;border-radius:14px 0 0 14px;background:linear-gradient(180deg,var(--red),var(--red2));color:#fff;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.9rem;padding:26px 0 18px;border-radius:0;box-shadow:-6px 0 24px rgba(230,51,18,.32);overflow:hidden;border-radius:14px 0 0 14px}
.stab-btn .lbl{writing-mode:vertical-rl;transform:rotate(180deg);font-family:'Barlow Semi Condensed',sans-serif;font-weight:800;font-size:1.22rem;letter-spacing:.2em;text-transform:uppercase;white-space:nowrap}
.stab-btn .lbl em{font-style:normal;color:#0A1A33}
.stab-btn .go{width:36px;height:36px;border-radius:50%;background:#fff;color:var(--red);display:flex;align-items:center;justify-content:center;transition:transform .3s}
.stab-btn .go svg{width:16px;height:16px}
.stab:hover .stab-btn .go{transform:translateX(-3px) scale(1.08)}
.stab-art{position:absolute;top:-6px;left:50%;transform:translateX(-50%);width:54px;opacity:.5;pointer-events:none}
.stab-btn::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent,rgba(255,255,255,.22),transparent);transform:translateY(-110%);animation:tabShine 4.5s ease-in-out infinite}
@keyframes tabShine{0%{transform:translateY(-110%)}60%{transform:translateY(110%)}100%{transform:translateY(110%)}}
@media (prefers-reduced-motion:reduce){.stab-btn::after{animation:none}}

