.stab-panel::after{content:"";position:absolute;top:0;left:-45%;width:34%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.26),transparent);transform:skewX(-20deg);animation:tabShine2 5s ease-in-out infinite}
@keyframes tabShine2{0%{left:-45%}58%{left:140%}100%{left:140%}}
.stab-lbl{position:relative;z-index:2;writing-mode:horizontal-tb;transform:none;font-family:Outfit,sans-serif;font-weight:800;font-size:1.22rem;letter-spacing:.03em;text-transform:uppercase;color:#fff;white-space:nowrap;margin:0;padding:0;text-shadow:none}
.stab-lbl em{font-style:normal;color:#0A1A33}
.stab-go{position:relative;z-index:2;width:auto;background:transparent;padding:0;border-radius:0;clip-path:none;display:flex;align-items:center}
.stab-go span{width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;color:#fff;transition:transform .3s,background .3s}
.stab-go span svg{width:18px;height:18px}
.stab:hover .stab-go span{background:#fff;color:var(--red);transform:translateX(4px)}
.stab-art2,.stab-drip,.stab-head{display:none!important}
.totop{left:22px;bottom:22px;right:auto}
@media(max-width:1180px){.stab{display:none}.totop{left:14px;bottom:70px}}
