@media(max-width:1200px){.hsin{padding:52px 40px 22px}
 .hero .hbadge2{margin:0 40px 14px;max-width:calc(100% - 80px)}
 .hero .hrate{margin:0 40px 34px;max-width:calc(100% - 80px)}}
