 @media(min-width:1201px){.hero h1{font-size:clamp(2rem,3.3vw,3.5rem)}.hero h1 em{white-space:normal}}
}

/* ============ service page ============ */
.svc{background:#fff}
.svc header.site,.svc header.site.bandbg{position:sticky;top:0;background:#fff;box-shadow:0 2px 24px rgba(10,26,51,.09);border-bottom:1px solid rgba(10,26,51,.07);animation:none}
.svc .util{background:var(--navy);padding-top:0}
.svc .util .wrap{padding-top:0;padding-bottom:0}
.svc .util-pill{background:transparent;box-shadow:none;border-radius:0;padding:.5rem 0}
.svc .util-pill::after{display:none}

/* --- hero --- */
.shero{position:relative;overflow:hidden;background:var(--navy)}
.shero-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 58%}
.shero::after{content:"";position:absolute;inset:0;
 background:linear-gradient(100deg,rgba(6,16,30,.88) 0%,rgba(6,16,30,.72) 28%,rgba(7,20,38,.38) 54%,rgba(7,20,38,.22) 74%,rgba(9,24,44,.36) 100%),
 linear-gradient(180deg,rgba(6,16,30,.42) 0%,transparent 24%,transparent 72%,rgba(6,16,30,.4) 100%)}
.shero::before{content:"";position:absolute;right:-8%;top:-40%;width:46%;height:190%;background:radial-gradient(circle,rgba(0,144,216,.22),transparent 64%);z-index:1}
.shero>.wrap{position:relative;z-index:3;max-width:1400px;padding-top:70px;padding-bottom:78px;display:grid;grid-template-columns:minmax(0,1.18fr) minmax(0,.82fr);gap:56px;align-items:center}
.crumb{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;font-size:.88rem;color:#9FBCD6;margin-bottom:1.3rem}
.crumb a{color:#C6DCEF;font-weight:600}
.crumb a:hover{color:#fff}
.crumb svg{width:13px;height:13px;color:#5E7E9C}
.crumb span[aria-current]{color:#fff;font-weight:600}
.shero h1{color:#fff;font-size:clamp(2.1rem,4.4vw,3.9rem);line-height:1.04;margin:0;text-shadow:0 2px 22px rgba(4,12,24,.5)}
.shero h1 em{font-style:normal;color:var(--blue2);display:block}
.shero .eyebrow{color:var(--blue2);font-family:Outfit,sans-serif;font-weight:700;letter-spacing:.01em;text-transform:none;font-size:1.02rem}
.shero .eyebrow::before{display:none}
.shero .sub{font-size:1.1rem;color:#D3E4F3;margin:1.2rem 0 1.7rem;max-width:36rem;line-height:1.68;text-shadow:0 1px 14px rgba(4,12,24,.55)}
.shero-cta{display:flex;gap:.9rem;flex-wrap:wrap;align-items:center}
.shero-chips{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1.6rem}
.shero-chips span{display:inline-flex;align-items:center;gap:.4rem;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.2);padding:.42rem .9rem;border-radius:999px;font-size:.86rem;font-weight:600;color:#fff}
.shero-chips svg{width:14px;height:14px;color:var(--blue2)}

/* at-a-glance panel (no form, no photo) */
.glance{background:linear-gradient(150deg,rgba(9,22,40,.78),rgba(9,22,40,.62));border:1px solid rgba(255,255,255,.18);border-radius:20px;padding:30px 30px 26px;backdrop-filter:blur(14px) saturate(1.1);box-shadow:0 26px 64px rgba(4,12,24,.5);min-width:0}
.glance h2{color:#fff;font-size:1.18rem;letter-spacing:.14em;text-transform:uppercase;font-weight:800;margin-bottom:1.2rem;display:flex;align-items:center;gap:.6rem}
.glance h2::before{content:"";width:26px;height:3px;border-radius:2px;background:var(--red);flex:none}
.gstats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-bottom:1.4rem}
.gstat{background:rgba(7,18,34,.42);border:1px solid rgba(255,255,255,.12);border-radius:13px;padding:14px 16px;min-width:0}
.gstat b{display:block;font-family:Outfit,sans-serif;font-weight:800;font-size:1.7rem;color:#fff;line-height:1}
.gstat small{display:block;font-size:.78rem;color:#9FBCD6;margin-top:.3rem;line-height:1.35}
.glist{list-style:none;display:grid;gap:.1rem}
.glist li{display:flex;align-items:flex-start;gap:.65rem;padding:.52rem 0;border-bottom:1px solid rgba(255,255,255,.1);color:#D7E6F3;font-size:.94rem}
.glist li:last-child{border-bottom:0}
.glist svg{width:20px;height:20px;color:#fff;background:var(--blue);border-radius:50%;padding:4px;flex:none;margin-top:.1rem}
.gfoot{display:flex;align-items:center;gap:.75rem;margin-top:1.3rem;padding-top:1.2rem;border-top:1px solid rgba(255,255,255,.16)}
.gfoot .ic{width:46px;height:46px;border-radius:50%;background:var(--red);color:#fff;display:flex;align-items:center;justify-content:center;flex:none}
.gfoot .ic svg{width:21px;height:21px}
.gfoot small{display:block;font-size:.74rem;letter-spacing:.09em;text-transform:uppercase;color:#9FBCD6;font-weight:600}
.gfoot b{font-family:Outfit,sans-serif;font-weight:800;font-size:1.3rem;color:#fff;line-height:1.1}
.gfoot a:hover b{color:var(--blue2)}

/* --- 2/3 + 1/3 body --- */
.svcbody{padding:78px 0 86px;background:#fff}
.svcbody>.wrap{max-width:1400px;display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:56px;align-items:start}
.svcmain{min-width:0}
.svcmain>section+section{margin-top:56px}
.svcmain h2{font-size:clamp(1.7rem,2.5vw,2.3rem);margin-bottom:.9rem}
.svcmain h3{font-size:1.22rem;margin-bottom:.35rem}
.svcmain p{color:var(--mut);margin-bottom:1rem}
.svcmain p:last-child{margin-bottom:0}
.svcmain .eyebrow{margin-bottom:.5rem}
.lead-in{font-size:1.1rem;color:var(--ink);line-height:1.75}

/* signs grid */
.signs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:1.4rem}
.sign{display:flex;gap:.9rem;align-items:flex-start;background:var(--bg);border:1px solid var(--line);border-radius:14px;padding:18px 20px;min-width:0;transition:.22s}
.sign:hover{background:#fff;border-color:var(--blue);box-shadow:0 14px 30px rgba(10,26,51,.1);transform:translateY(-3px)}
.sign .ic{width:44px;height:44px;border-radius:12px;background:var(--blue-soft);color:var(--blue);display:flex;align-items:center;justify-content:center;flex:none}
.sign .ic svg{width:21px;height:21px}
.sign b{display:block;font-family:Outfit,sans-serif;font-weight:700;font-size:1rem;color:var(--navy);margin-bottom:.15rem}
.sign small{color:var(--mut);font-size:.9rem;line-height:1.5}

/* numbered method blocks */
.method{display:grid;gap:18px;margin-top:1.5rem;counter-reset:mt}
.mrow{display:grid;grid-template-columns:72px minmax(0,1fr);gap:20px;background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px 24px;align-items:start;transition:.22s;position:relative;overflow:hidden}
.mrow::after{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--red);transform:scaleY(0);transform-origin:top;transition:transform .3s}
.mrow:hover{box-shadow:0 18px 38px rgba(10,26,51,.12);border-color:transparent}
.mrow:hover::after{transform:scaleY(1)}
.mnum{counter-increment:mt;width:72px;height:72px;border-radius:16px;background:linear-gradient(145deg,var(--navy),var(--navy3));color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;flex:none}
.mnum::before{content:"0" counter(mt);font-family:Outfit,sans-serif;font-weight:800;font-size:1.3rem;line-height:1}
.mnum svg{width:20px;height:20px;color:var(--blue2)}
.mrow p{margin:0;font-size:.97rem}

/* image band */
.svcshot{border-radius:18px;overflow:hidden;margin-top:1.6rem;position:relative}
.svcshot img{width:100%;aspect-ratio:16/8;object-fit:cover;display:block}
.svcshot figcaption{position:absolute;left:0;right:0;bottom:0;padding:34px 24px 18px;background:linear-gradient(180deg,transparent,rgba(10,26,51,.9));color:#fff;font-size:.92rem;font-weight:600}

/* compare table */
.cmp{width:100%;border-collapse:separate;border-spacing:0;border:1px solid var(--line);border-radius:16px;overflow:hidden}
.cmp th,.cmp td{padding:15px 18px;text-align:left;font-size:.95rem;border-bottom:1px solid var(--line)}
.cmp thead th{background:var(--navy);color:#fff;font-family:Outfit,sans-serif;font-weight:700;font-size:.92rem;letter-spacing:.04em;text-transform:uppercase;border-bottom:0}
.cmp tbody tr:last-child th,.cmp tbody tr:last-child td{border-bottom:0}
.cmp tbody th{font-weight:700;color:var(--navy);background:var(--bg);width:34%}
.cmp td{color:var(--mut)}
.cmp td.yes{color:var(--green);font-weight:700}
.cwrap{overflow-x:auto;max-width:100%;margin-top:1.4rem;-webkit-overflow-scrolling:touch}
.cwrap .cmp{margin-top:0;min-width:520px}

/* callout */
.callout{display:flex;gap:1rem;align-items:flex-start;background:linear-gradient(135deg,var(--blue-soft),#fff);border:1px solid rgba(0,144,216,.25);border-left:5px solid var(--blue);border-radius:14px;padding:22px 24px;margin-top:1.5rem}
.callout .ic{width:44px;height:44px;border-radius:50%;background:var(--blue);color:#fff;display:flex;align-items:center;justify-content:center;flex:none}
.callout .ic svg{width:21px;height:21px}
.callout b{display:block;font-family:Outfit,sans-serif;font-weight:800;color:var(--navy);margin-bottom:.2rem}
.callout p{margin:0;font-size:.96rem}

/* --- sidebar --- */
.svcside{min-width:0;position:sticky;top:118px;display:grid;gap:20px}
.sbox{border:1px solid var(--line);border-radius:18px;overflow:hidden;background:#fff}
.sbox-h{padding:16px 22px;font-family:Outfit,sans-serif;font-weight:800;font-size:1.02rem;letter-spacing:.1em;text-transform:uppercase;color:#fff;background:var(--navy);display:flex;align-items:center;gap:.6rem}
.sbox-h svg{width:18px;height:18px;color:var(--blue2)}
.sbox-b{padding:20px 22px}
.sbox-b p{color:var(--mut);font-size:.94rem;margin-bottom:1rem}
.slinks{list-style:none;display:grid}
.slinks li{border-bottom:1px solid var(--line)}
.slinks li:last-child{border-bottom:0}
.slinks a{display:flex;align-items:center;justify-content:space-between;gap:.7rem;padding:.78rem 0;font-weight:600;color:var(--navy);font-size:.96rem;transition:.2s}
.slinks a svg{width:15px;height:15px;color:var(--blue);transition:transform .22s;flex:none}
.slinks a:hover{color:var(--blue)}
.slinks a:hover svg{transform:translateX(4px)}
.slinks a.on{color:var(--blue)}
.scall{background:linear-gradient(150deg,var(--navy) 0%,#0B2140 58%,var(--navy2) 100%);border-radius:18px;padding:26px 24px;color:#D7E6F3;text-align:center;position:relative;overflow:hidden}
.scall::after{content:"";position:absolute;right:-30%;top:-60%;width:80%;height:200%;background:radial-gradient(circle,rgba(0,144,216,.34),transparent 62%)}
.scall>*{position:relative;z-index:2}
.scall h3{color:#fff;font-size:1.3rem;margin-bottom:.4rem}
.scall p{color:#AFC6DC;font-size:.92rem;margin-bottom:1.2rem}
.scall .btn{width:100%;margin-bottom:.6rem}
.scall .ph{display:inline-flex;align-items:center;gap:.5rem;color:#fff;font-family:Outfit,sans-serif;font-weight:800;font-size:1.26rem;margin-top:.5rem}
.scall .ph svg{width:18px;height:18px;color:var(--blue2)}
.sfacts{list-style:none;display:grid;gap:.1rem}
.sfacts li{display:flex;gap:.7rem;align-items:flex-start;padding:.6rem 0;border-bottom:1px solid var(--line);font-size:.93rem;color:var(--mut)}
.sfacts li:last-child{border-bottom:0}
.sfacts svg{width:18px;height:18px;color:var(--blue);flex:none;margin-top:.15rem}
.sfacts b{display:block;color:var(--navy);font-family:Outfit,sans-serif;font-weight:700;font-size:.95rem;margin-bottom:.1rem}
.sareas{display:flex;flex-wrap:wrap;gap:.4rem}
.sareas a{background:var(--bg);border:1px solid var(--line);padding:.4rem .8rem;border-radius:999px;font-size:.84rem;font-weight:600;color:var(--navy);transition:.2s}
.sareas a:hover{background:var(--navy);border-color:var(--navy);color:#fff}
.sbadge{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.sbadge img{width:100%;height:auto;border-radius:9px;background:#fff;border:1px solid var(--line);padding:7px 9px}

/* --- faq + cta --- */
.svcfaq{background:var(--bg);padding:72px 0}
.svcfaq>.wrap{max-width:900px}
.svccta{padding:0 0 86px;background:#fff}
.svccta>.wrap{max-width:1400px}

